(7920, 'wppb_admin_emailc_common_settings_header', 'These settings are also replicated in the \"User Email Customizer\" settings-page upon save. Valid tags {{reply_to}} and {{site_name}}', 'yes'),
(7921, 'wppb_emailc_common_settings_from_name', '{{site_name}}', 'yes'),
(7922, 'wppb_emailc_common_settings_from_reply_to_email', '{{reply_to}}', 'yes'),
(7923, 'wppb_admin_emailc_default_registration_email_subject', '[{{site_name}}] A new subscriber has (been) registered!', 'yes'),
(7924, 'wppb_admin_emailc_default_registration_email_content', '<p>New subscriber on {{site_name}}.</p>\n<p>Username:{{username}}</p>\n<p>E-mail:{{user_email}}</p>\n', 'yes'),
(7925, 'wppb_admin_emailc_registration_with_admin_approval_email_subject', '[{{site_name}}] A new subscriber has (been) registered!', 'yes'),
(7926, 'wppb_admin_emailc_registration_with_admin_approval_email_content', '<p>New subscriber on {{site_name}}.</p>\n<p>Username:{{username}}</p>\n<p>E-mail:{{user_email}}</p>\n<p>The Admin Approval feature was activated at the time of registration,\nso please remember that you need to approve this user before he/she can log in!</p>', 'yes'),
(7927, 'wppb_admin_emailc_user_password_reset_email_subject', '[{{site_name}}] Password Successfully Reset for {{username}}', 'yes'),
(7928, 'wppb_admin_emailc_user_password_reset_email_content', '<p>{{username}} has requested a password change via the password reset feature.</p>\n<p>His/her new password is: {{password}}</p>\n', 'yes'),
(7929, 'wppb_user_emailc_default_registration_email_subject', 'A new account has been created for you on {{site_name}}', 'yes'),
(7930, 'wppb_user_emailc_default_registration_email_content', '<h3>Welcome to {{site_name}}!</h3>\n<p>Your username is:{{username}} and password:{{password}}</p>\n', 'yes'),
(7931, 'wppb_user_emailc_registr_w_email_confirm_email_subject', '[{{site_name}}] Activate {{username}}', 'yes'),
(7932, 'wppb_user_emailc_registr_w_email_confirm_email_content', '<p>To activate your user, please click the following link:<br/>\n{{{activation_link}}}</p>\n<p>After you activate, you will receive another email with your credentials.</p>\n', 'yes'),
(7933, 'wppb_user_emailc_registration_with_admin_approval_email_subject', 'A new account has been created for you on {{site_name}}', 'yes'),
(7934, 'wppb_user_emailc_registration_with_admin_approval_email_content', '<h3>Welcome to {{site_name}}!</h3>\n<p>Your username is:{{username}} and password:{{password}}</p>\n<p>Before you can access your account, an administrator needs to approve it. You will be notified via email.</p>\n', 'yes'),
(7935, 'wppb_user_emailc_admin_approval_notif_approved_email_subject', 'Your account on {{site_name}} has been approved!', 'yes'),
(7936, 'wppb_user_emailc_admin_approval_notif_approved_email_content', '<h3>Good News!</h3>\n<p>An administrator has just approved your account: {{username}} on {{site_name}}.</p>\n', 'yes'),
(7937, 'wppb_user_emailc_admin_approval_notif_unapproved_email_subject', 'Your account on {{site_name}} has been unapproved!', 'yes'),
(7938, 'wppb_user_emailc_admin_approval_notif_unapproved_email_content', '<h3>Hello,</h3>\n<p>Unfortunatelly an administrator has just unapproved your account: {{username}} on {{site_name}}.</p>\n', 'yes'),
(7939, 'wppb_user_emailc_reset_email_subject', '[{{site_name}}] Password Reset', 'yes'),
(7940, 'wppb_user_emailc_reset_email_content', '<p>Someone requested that the password be reset for the following account: {{site_name}}<br/>\nUsername: {{username}}</p>\n<p>If this was a mistake, just ignore this email and nothing will happen.</p>\n<p>To reset your password, visit the following address:<br/>\n{{{reset_link}}}</p>\n', 'yes'),
(7941, 'wppb_user_emailc_reset_success_email_subject', '[{{site_name}}] Password Reset Successfully', 'yes'),
(7942, 'wppb_user_emailc_reset_success_email_content', '<p>You have successfully reset your password.</p>\n', 'yes'),
(7943, 'wppb_user_emailc_change_email_address_subject', '[{{site_name}}] Notice of Email Change', 'yes'),
(7944, 'wppb_user_emailc_change_email_address_content', '<h3>Hi {{username}},</h3>\n<p>This notice confirms that your email was changed on {{site_name}}.</p>\n<p>If you did not change your email, please contact the Site Administrator at ann.visloguzova@gmail.com</p>\n<p>This email has been sent to {{user_email}}</p>\n<p>Regards,<br>\nAll at {{site_name}}<br>\n<a href=\"{{site_url}}\">{{site_url}}</a></p>', 'yes'),
