(2388, 'booking_search_form_show', '<div class=\"wpdevelop\">\r\n    <div class=\"form-inline well\">\r\n<div class=\"w40\">\r\n<label>Заезд:</label>\r\n<div class=\"wpcf7-form-control-wrap\">\r\n      [search_check_in]\r\n</div>\r\n</div>\r\n<div class=\"w40\">\r\n<label>Выезд:</label>\r\n<div class=\"wpcf7-form-control-wrap\">\r\n      [search_check_out]\r\n</div>\r\n</div>\r\n[search_button]\r\n</div>\r\n</div>\r\n[lang=en_US]\r\n<div class=\"wpdevelop\">\r\n    <div class=\"form-inline well\">\r\n<div class=\"w40\">\r\n<label>Check in:</label>\r\n<div class=\"wpcf7-form-control-wrap\">\r\n      [search_check_in]\r\n</div>\r\n</div>\r\n<div class=\"w40\">\r\n<label>Departure:</label>\r\n<div class=\"wpcf7-form-control-wrap\">\r\n      [search_check_out]\r\n</div>\r\n</div>\r\n[search_button]\r\n</div>\r\n</div>', 'yes'),
(2389, 'booking_found_search_item', '<div class=\"item\">\r\n              <div class=\"image wow fadeInUp\">\r\n                <span class=\"status\"></span>\r\n                <div class=\"slider-img\">\r\n                  <div class=\"img-item\">\r\n                     [booking_featured_image]\r\n                  </div>\r\n                \r\n                </div>\r\n              </div>\r\n              <div class=\"text\">\r\n                <div class=\"text-wrap\">\r\n                  <p class=\"h4\">[booking_resource_title]</p>\r\n                  <div class=\"price-block\">\r\n                    <p class=\"price\">[standard_cost]</p>\r\n                    <a href=\"[book_now_link]\" class=\"btn\">подробнее</a>\r\n                  </div>\r\n\r\n                </div>\r\n\r\n              </div>\r\n            </div>\r\n[lang=en_US]\r\n<div class=\"item\">\r\n              <div class=\"image wow fadeInUp\">\r\n                <span class=\"status\"></span>\r\n                <div class=\"slider-img\">\r\n                  <div class=\"img-item\">\r\n                     [booking_featured_image]\r\n                  </div>\r\n                \r\n                </div>\r\n              </div>\r\n              <div class=\"text\">\r\n                <div class=\"text-wrap\">\r\n                  <p class=\"h4\">[booking_resource_title]</p>\r\n                  <div class=\"price-block\">\r\n                    <p class=\"price\">[standard_cost]</p>\r\n                    <a href=\"[book_now_link]\" class=\"btn\">more</a>\r\n                  </div>\r\n\r\n                </div>\r\n\r\n              </div>\r\n            </div>', 'yes'),
