(7860, 'wppb_general_settings', 'a:9:{s:17:\"extraFieldsLayout\";s:7:\"default\";s:17:\"emailConfirmation\";s:2:\"no\";s:21:\"activationLandingPage\";s:0:\"\";s:13:\"adminApproval\";s:2:\"no\";s:23:\"adminApprovalOnUserRole\";a:4:{i:0;s:6:\"editor\";i:1;s:6:\"author\";i:2;s:11:\"contributor\";i:3;s:10:\"subscriber\";}s:11:\"rolesEditor\";s:3:\"yes\";s:9:\"loginWith\";s:5:\"email\";s:23:\"minimum_password_length\";s:0:\"\";s:25:\"minimum_password_strength\";s:0:\"\";}', 'yes'),
(8323, 'trp_settings', 'a:12:{s:16:\"default-language\";s:5:\"ru_RU\";s:21:\"translation-languages\";a:1:{i:0;s:5:\"ru_RU\";}s:17:\"publish-languages\";a:1:{i:0;s:5:\"ru_RU\";}s:22:\"native_or_english_name\";s:12:\"english_name\";s:36:\"add-subdirectory-to-default-language\";s:2:\"no\";s:30:\"force-language-to-custom-links\";s:3:\"yes\";s:11:\"g-translate\";s:2:\"no\";s:14:\"trp-ls-floater\";s:3:\"yes\";s:17:\"shortcode-options\";s:16:\"flags-full-names\";s:12:\"menu-options\";s:16:\"flags-full-names\";s:15:\"floater-options\";s:16:\"flags-full-names\";s:9:\"url-slugs\";a:2:{s:5:\"en_US\";s:2:\"en\";i:0;s:0:\"\";}}', 'yes'),
(8324, 'trp_plugin_version', '1.3.8', 'yes'),
(6217, 'acf_pro_license', 'YToyOntzOjM6ImtleSI7czo3MjoiYjNKa1pYSmZhV1E5TkRBME5EUjhkSGx3WlQxa1pYWmxiRzl3WlhKOFpHRjBaVDB5TURFMExUQTVMVEl6SURJd09qRTRPakV6IjtzOjM6InVybCI7czoyMToiaHR0cDovL25ha3ZhcnRpcmUuY29tIjt9', 'yes'),
(7858, 'wppb-ul-templates', '\r\n<table class=\"wppb-table\">\r\n	<thead>\r\n		<tr>\r\n		  <th scope=\"col\" colspan=\"2\" class=\"wppb-sorting\">{{{sort_user_name}}}</th>\r\n		  <th scope=\"col\" class=\"wppb-sorting\">{{{sort_first_name}}}</th>\r\n		  <th scope=\"col\" class=\"wppb-sorting\">{{{sort_role}}}</th>\r\n		  <th scope=\"col\" class=\"wppb-sorting\">{{{sort_number_of_posts}}}</th>\r\n		  <th scope=\"col\" class=\"wppb-sorting\">{{{sort_registration_date}}}</th>\r\n		  <th scope=\"col\">More</th>\r\n		</tr>\r\n	</thead>	\r\n	<tbody>\r\n		{{#users}}\r\n		<tr>\r\n		  <td data-label=\"Avatar\" class=\"wppb-avatar\">{{{avatar_or_gravatar}}}</td>\r\n		  <td data-label=\"Username\" class=\"wppb-login\">{{meta_user_name}}</td>\r\n		  <td data-label=\"Firstname\" class=\"wppb-name\">{{meta_first_name}} {{meta_last_name}}</td>\r\n		  <td data-label=\"Role\" class=\"wppb-role\">{{meta_role}}</td>\r\n		  <td data-label=\"Posts\" class=\"wppb-posts\">{{{meta_number_of_posts}}}</td>\r\n		  <td data-label=\"Sign-up Date\" class=\"wppb-signup\">{{meta_registration_date}}</td>\r\n		  <td data-label=\"More\" class=\"wppb-moreinfo\">{{{more_info}}}</td>\r\n		</tr>\r\n		{{/users}}\r\n	</tbody>\r\n</table>\r\n{{{pagination}}}', 'yes'),
(7859, 'wppb-single-ul-templates', '\r\n{{{extra_go_back_link}}}\r\n<ul class=\"wppb-profile\">\r\n  <li>\r\n    <h3>Name</h3>\r\n  </li>\r\n  <li class=\"wppb-avatar\">\r\n    {{{avatar_or_gravatar}}}\r\n  </li>\r\n  <li>\r\n    <label>Username:</label>\r\n    <span>{{meta_user_name}}</span>\r\n  </li>\r\n  <li>\r\n    <label>First Name:</label>\r\n    <span>{{meta_first_name}}</span>\r\n  </li>\r\n  <li>\r\n    <label>Last Name:</label>\r\n    <span>{{meta_last_name}}</span>\r\n  </li>\r\n  <li>\r\n    <label>Nickname:</label>\r\n    <span>{{meta_nickname}}</span>\r\n  </li>\r\n  <li>\r\n    <label>Display name:</label>\r\n	<span>{{meta_display_name}}</span>\r\n  </li>\r\n  <li>\r\n    <h3>Contact Info</h3>\r\n  </li>\r\n  <li>\r\n  	<label>Website:</label>\r\n	<span>{{meta_website}}</span>\r\n  </li>\r\n  <li>\r\n    <h3>About Yourself</h3>\r\n  </li>\r\n  <li>\r\n	<label>Biographical Info:</label>\r\n	<span>{{{meta_biographical_info}}}</span>\r\n  </li>\r\n</ul>\r\n{{{extra_go_back_link}}}', 'yes'),
