(11113, 809, 'additional_information_banners_blok_4_title', 'Customer Service'),
(11114, 809, 'additional_information_banners_blok_4_img', '302'),
(11115, 809, 'additional_information_banners_blok_4_descr', '<strong>Service suggestions and comments</strong>\r\nIf you have any questions about the quality of service,\r\nor suggestions for improving our work, write WhatsApp +7(985)100-56-88 / +7(985)100-54-57 mail nakvartirerf@gmail.com'),
