(12490, 822, 'additional_information_banners_blok_1_descr', '<strong>Allowed</strong>\r\n<ul>\r\n 	<li>spend time at home with family</li>\r\n 	<li>cook food on the stove and in the oven</li>\r\n 	<li>washing clothes in a washing machine</li>\r\n 	<li>smoke on the balcony with the door closed</li>\r\n 	<li>use internet and cable tv</li>\r\n</ul>\r\n<strong>Prohibited</strong>\r\n<ul>\r\n 	<li>parties at home</li>\r\n 	<li>celebrate holidays</li>\r\n 	<li>smoking in the apartment</li>\r\n 	<li>litter in the apartment</li>\r\n 	<li>make noise in the apartment</li>\r\n 	<li>carelessly treat property in an apartment</li>\r\n 	<li>the presence of more people than in the contract</li>\r\n</ul>'),
(12555, 822, '_additional_information_banners_blok_1_descr', 'field_5b17c552b33b4'),
