(14141, 835, 'additional_information_banners_blok_1_descr', '<strong>Allowed</strong>\r\n<ul>\r\n 	<li>spend time at home with family</li>\r\n 	<li>cook food on the stove and in the oven</li>\r\n 	<li>washing clothes in a washing machine</li>\r\n 	<li>smoke on the balcony with the door closed</li>\r\n 	<li>use internet and cable tv</li>\r\n</ul>\r\n<strong>Prohibited</strong>\r\n<ul>\r\n 	<li>parties at home</li>\r\n 	<li>celebrate holidays</li>\r\n 	<li>smoking in the apartment</li>\r\n 	<li>litter in the apartment</li>\r\n 	<li>make noise in the apartment</li>\r\n 	<li>carelessly treat property in an apartment</li>\r\n 	<li>the presence of more people than in the contract</li>\r\n</ul>'),
(14206, 835, '_additional_information_banners_blok_1_descr', 'field_5b17c552b33b4'),
(14207, 835, '_additional_information_banners_blok_1', 'field_5b17c480b33b1'),
(14208, 835, '_additional_information_banners_blok_2_title', 'field_5b17c573b33b6'),
(14142, 835, 'additional_information_banners_blok_1', ''),
(14143, 835, 'additional_information_banners_blok_2_title', 'Free services'),
(14144, 835, 'additional_information_banners_blok_2_img', '305'),
(14145, 835, 'additional_information_banners_blok_2_descr', '<p style=\"text-align: left;\"><strong>Linens</strong>\r\nWe suggest one bed linen to one bed. The coast of using extra linens is 200 rubles and towel 100 rubles.\r\n<strong>Movie collection</strong>\r\nEach apartment has a flash drive with free movies, on which about 20 interesting movies of different genres. For the flash drive we take 700 rub. deposit and return it when you check-out.\r\n<strong>Wi-fi internet and cable TV</strong>\r\nEach apartment has a memo with a password of Wi-Fi.</p>'),
(14210, 835, '_additional_information_banners_blok_2_descr', 'field_5b17c573b33b8'),
(14211, 835, '_additional_information_banners_blok_2', 'field_5b17c573b33b5'),
